out=pathlib.Path('research/results-group2');url='https://s3.amazonaws.com/dl.ncsbe.gov/ENRS/2026_03_03/results_pct_20260303.zip'; layout='https://s3.amazonaws.com/dl.ncsbe.gov/ENRS/layout_results_pct.txt'; gov='https://www.ncsbe.gov/results-data/election-results/historical-election-results-data'
with urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'ElectionTracker official public results research/1.0'}),timeout=45) as r:b=r.read(32*1024*1024+1);proof={'url':url,'governmentLanding':gov,'governmentLinkText':'2026 Mar03 Election - Results (ZIP)','status':r.status,'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'lastModified':r.headers.get('Last-Modified'),'contentType':r.headers.get('Content-Type'),'zipSha256':hashlib.sha256(b).hexdigest(),'zipBytes':len(b)}
