file=next(n for n in names if n.endswith('.txt'));info=z.getinfo(file);assert info.file_size<=96*1024*1024;data=z.read(file);rows=list(csv.DictReader(io.StringIO(data.decode('utf-8-sig')),delimiter='\t'));print('columns',list(rows[0]));print('rowCount',len(rows));print('firstVotes',json.dumps(rows[0]));print('sampleContests',list(dict.fromkeys(r.get('Contest Name') or r.get('contest_name') or r.get('contest name') or '' for r in rows))[:15]);proof.update(entry=file,entrySha256=hashlib.sha256(data).hexdigest(),entryBytes=len(data),fullRowCount=len(rows),columns=list(rows[0]),trueElectionDate='2026-03-03',phase='primary',notTargetNovemberGeneral=True,layoutUrl=layout,certificationDeclaration=None,sourceAsOf=None)
